254		rec := syntheticRecord(org, 1, AuditDecision, nil, &DecisionRecord{
255			Request:  request(org, "u1", "r1", "org/a", "read"),
256			Decision: Decision{Allowed: false, Reason: s, Version: 0},
257		}, genesisFingerprint(org))
