261	// TestArchiveEncodingRejectsInvalidMaterial ensures encode validates the
262	// whole material and hands back no bytes on failure.
263	func TestArchiveEncodingRejectsInvalidMaterial(t *testing.T) {
264		s := NewStore()
265		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
266		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
