404	// TestArchiveDecodeContentValidation ensures decode validates the entire
405	// material against the caller's retained checkpoint and expected org.
406	func TestArchiveDecodeContentValidation(t *testing.T) {
407		s := NewStore()
408		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
409		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
