436				t.Fatalf("checkpoint %+v err = %v, want ErrInvalidRange", wrong, err)
437			}
438		}
439	
440		// Damage confined to a record after the one the caller plans to review
441		// still fails the whole read.
442		late := reframe(t, good, func(payload []byte) []byte {
443			idx := bytes.Index(payload, []byte("late-victim"))
444			if idx < 0 {
445				t.Fatal("late record subject not found in payload")
446			}
447			payload[idx] ^= 0x01
448			return payload
449		})
450		if _, err := DecodeAuditArchive(late, "acme", cp); !errors.Is(err, ErrInvalidRange) {
451			t.Fatalf("late-record damage err = %v, want ErrInvalidRange", err)
452		}
453	
454		// An archive of another organization cannot be read as acme even with
455		// acme-shaped caller data.
456		grecs, gcp, _ := NewStore().AuditExport("globex", 0)
457		garchive, err := EncodeAuditArchive("globex", grecs, gcp)
458		if err != nil {
459			t.Fatal(err)
460		}
461		if _, err := DecodeAuditArchive(garchive, "acme", cp); !errors.Is(err, ErrInvalidRange) {
462			t.Fatalf("cross-org archive err = %v", err)
463		}
464	}
