473		good, err := EncodeAuditArchive("acme", recs, cp)
474		if err != nil {
475			t.Fatal(err)
476		}
477	
478		// Re-frame the same records with a different embedded end sequence: the
479		// caller's retained checkpoint must be the one that decides.
480		rewritten := reframe(t, good, func(payload []byte) []byte {
481			// Header layout: u32 orgLen, org, u32 endSeq, u32 fpLen, fp, ...
482			pos := 4 + len("acme")
483			binary.BigEndian.PutUint32(payload[pos:pos+4], 999)
484			return payload
485		})
486		if _, err := DecodeAuditArchive(rewritten, "acme", cp); !errors.Is(err, ErrInvalidRange) {
487			t.Fatalf("altered embedded metadata must not be trusted: err = %v", err)
488		}
489	}
