491	// TestArchiveInconsistentDecisionIsNotArchiveDamage archives a chain that
492	// is internally valid but whose recorded decision contradicts the recorded
493	// policy: decode succeeds, and offline review reports the inconsistency.
494	func TestArchiveInconsistentDecisionIsNotArchiveDamage(t *testing.T) {
495		req := request("acme", "u1", "r1", "org/a", "read")
496		recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
497			func(seq int) (string, *PolicyChange, *DecisionRecord) {
498				return AuditPolicyChange, &PolicyChange{
499					Version:  1,
500					Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
501				}, nil
502			},
503			func(seq int) (string, *PolicyChange, *DecisionRecord) {
504				return AuditDecision, nil, &DecisionRecord{
505					Request:  req,
506					Decision: Decision{Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
507				}
508			},
509		})
510		archive, err := EncodeAuditArchive("acme", recs, cp)
511		if err != nil {
512			t.Fatal(err)
513		}
514		got, err := DecodeAuditArchive(archive, "acme", cp)
515		if err != nil {
516			t.Fatalf("a decision disagreement is not archive damage: %v", err)
517		}
518		review, err := RecheckDecisionOffline("acme", got, cp, 2)
519		if err != nil {
