	// publish sits at seq 2 and is filtered out of this view).
	wantSeqs := []int{1, 3, 4, 5, 6, 7, 8}
	gotSeqs := make([]int, len(recs))
	for i, r := range recs {
		gotSeqs[i] = r.Seq
	}
	if !reflect.DeepEqual(gotSeqs, wantSeqs) {
		t.Fatalf("decision seqs = %v, want %v", gotSeqs, wantSeqs)
	}
