//   - a boolean marker (0/1) for every bool the material carries — whether a
//     policy is recursive, whether a change came from a rollback, whether a
//     subject is disabled and whether a decision allowed the access; and
//   - a presence marker (0/1) telling nil apart from a present value: the
//     change and decision payloads of each record, a change's policy list,
//     and a decision's subject-role and matched-policy lists.
//
// Only the bytes 0 and 1 are legal at any of those positions. Every
// corruption below is reframed with a consistent outer length and checksum,
// so exercising these cases proves the rejection comes from the payload's
// own format check rather than the framing-level samples in
// audit_archive_test.go or the list-count guards in
// audit_archive_listcorrupt_test.go: a decoder that treated "any non-zero
// byte as true/present" would accept these. A value outside {0,1} must fail
// the whole read with ErrInvalidArchive and no records — never a decoded
// decision that merely looks usable.
//
// A different failure is kept separate: flipping a legal boolean byte
// between 0 and 1 leaves the format fully readable, but the content no
// longer matches the retained fingerprint; such material must fail as
// ErrInvalidRange through the audit-chain check, not as archive damage.
package darksafe

import (
	"bytes"
	"encoding/binary"
	"errors"
	"reflect"
	"strings"
	"testing"
)

// markerAt is one single-byte marker's position in a payload and the legal
// value a valid encoding carries there.
type markerAt struct {
	name string
	at   int
	want byte // the legal byte the valid fixture writes here
}

// markerFixtureSites locates every single-byte marker the fixture built by
// markerCorruptionFixture carries, in payload byte offsets. It mirrors
// archiveWriter and the three field tables, so a format change moves these
// tests off their target rather than silently corrupting the wrong byte.
type markerFixtureSites struct {
	// Payload markers of record 1 (the policy change) and record 2 (the
	// decision): the two payload presence markers per record.
	change1   markerAt
	decision1 markerAt
	change2   markerAt
	decision2 markerAt

	// Booleans, in encode order.
	recursive11 markerAt // policy[0].Recursive, record 1
	recursive12 markerAt // policy[1].Recursive, record 1
	rolledBack1 markerAt // change record 1
	disabled2   markerAt // subject of decision record 2
	allowed2    markerAt // decision record 2

	// nil-versus-present list markers.
	policies1 markerAt // the change's policy list (present)
	roles2    markerAt // the decision's subject roles (present)
	matched2  markerAt // the decision's matched-policy list (present)
}

// markerInspector walks the known-good, two-record fixture payload in
// encode order. It exists only to locate marker bytes; every visited offset
// is cross-checked against the legal value the fixture must carry there.
type markerInspector struct {
	b   []byte
	pos int
}

func (c *markerInspector) u32() int {
	v := int(binary.BigEndian.Uint32(c.b[c.pos : c.pos+4]))
	c.pos += 4
	return v
}

func (c *markerInspector) str() {
	n := c.u32()
	c.pos += n
}

// marker consumes and returns one marker byte, recording its position.
func (c *markerInspector) markerSite(name string, want byte) markerAt {
	m := c.b[c.pos]
	site := markerAt{name: name, at: c.pos, want: want}
	c.pos++
	if m != want {
		panic("markerInspector: fixture byte at " + name + " mismatch")
	}
	return site
}

// stringList walks a present string list (marker already consumed by the
// caller) so following offsets line up.
func (c *markerInspector) presentStringList() {
	n := c.u32()
	for i := 0; i < n; i++ {
		c.str()
	}
}

// policy walks one encoded policy in the single policy field table's order:
// five strings, the Recursive bool, the always-archived ResourceID string.
func (c *markerInspector) policy() {
	c.str() // ID
	c.str() // Subject
	c.str() // Action
	c.str() // Scope
	c.str() // Effect
	c.pos++ // Recursive bool
	c.str() // ResourceID
}

// inspectMarkerFixturePayload locates every marker of the two-record
// fixture built by markerCorruptionFixture.
func inspectMarkerFixturePayload(t *testing.T, p []byte) markerFixtureSites {
	t.Helper()
	c := &markerInspector{b: p}
	c.str()    // embedded org
	c.pos += 4 // embedded end sequence
	c.str()    // embedded checkpoint fingerprint
	if n := c.u32(); n != 2 {
		t.Fatalf("fixture record count = %d, want 2", n)
	}

	// Record 1: policy change with two policies, absent decision.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	sites := markerFixtureSites{}
	sites.change1 = c.markerSite("record 1 change payload", archiveTagPresent)
	c.pos += 4 // change version
	sites.policies1 = c.markerSite("record 1 policy list", archiveTagPresent)
	if n := c.u32(); n != 2 {
		t.Fatalf("record 1 policy count = %d, want 2", n)
	}
	// Recursive bool of each policy sits between its Effect and ResourceID.
	rec11 := c.pos
	c.policy()
	sites.recursive11 = markerSite{name: "policy[0].Recursive", at: rec11, want: 0}
	rec12 := c.pos
	c.policy()
	sites.recursive12 = markerSite{name: "policy[1].Recursive", at: rec12, want: 1}
	c.pos += 4 // source version
	sites.rolledBack1 = c.markerSite("change.RolledBack", 0)
	sites.decision1 = c.markerSite("record 1 decision payload", archiveTagNil)
	c.str() // prev fingerprint
	c.str() // own fingerprint
	rec1End := c.pos

	// Record 2: decision with a disabled subject, roles, and matched list.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	sites.change2 = c.markerSite("record 2 change payload", archiveTagNil)
	sites.decision2 = c.markerSite("record 2 decision payload", archiveTagPresent)
	c.str() // request SubjectOrg
	c.str() // request ResourceOrg
	c.str() // subject ID
	c.str() // subject Kind
	sites.roles2 = c.markerSite("decision subject roles", archiveTagPresent)
	c.presentStringList()
	sites.disabled2 = c.markerSite("subject.Disabled", 1)
	c.str() // resource ID
	c.str() // resource scope
	c.str() // action
	sites.allowed2 = c.markerSite("decision.Allowed", 0)
	c.str() // decision reason
	sites.matched2 = c.markerSite("decision matched list", archiveTagPresent)
	c.presentStringList()
	c.pos += 4 // decision version
	c.str()    // prev fingerprint
	c.str()    // own fingerprint

	if c.pos != len(p) {
		t.Fatalf("inspector ended at %d, payload length %d", c.pos, len(p))
	}
	if rec1End <= 0 {
		t.Fatal("record 1 end not recorded")
	}
	return sites
}

// markerCorruptionFixture builds complete, valid material exercising both
// values of every boolean and both shapes the presence markers describe:
//
//   - seq 1 is a publish of two policies, one flat (Recursive=false) and one
//     recursive (Recursive=true); the change is present (not a rollback),
//     its policy list present and populated, and the decision payload
//     absent.
//   - seq 2 is the recorded denial of a disabled subject against the
//     published version: Disabled=true, Allowed=false, the request carries
//     roles and the decision carries matched policies, the change payload is
//     absent and the decision payload present.
//
// The material is exported and archived through the public entry points and
// must decode and re-review consistently before any mutation.
func markerCorruptionFixture(t *testing.T) ([]byte, []AuditRecord, Checkpoint) {
	t.Helper()
	s := NewStore()
	s.Publish("acme", 0, []Policy{
		allowPolicy("p-flat", "u1", "read", "org/a", false),
		allowPolicy("p-rec", "u1", "read", "org/a", true),
	})
	disabledReq := request("acme", "u1", "r1", "org/a", "read")
	disabledReq.Subject.Roles = []string{"reader"}
	disabledReq.Subject.Disabled = true
	original := s.Decide("acme", disabledReq)
	if original.Allowed || original.Reason != "subject is disabled" {
		t.Fatalf("fixture decision = %+v, want the disabled-subject denial", original)
	}
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode fixture: %v", err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("fixture must decode: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil || !review.Consistent || !reflect.DeepEqual(review.Original, original) {
		t.Fatalf("fixture review = %+v, %v", review, err)
	}
	return archive, recs, cp
}

// markerCorruptionCases lists every single-byte marker the requirement
// names: four booleans (recursive appears twice, for its 0 and 1 legal
// values), the two payloads of each record kind, and the policy, role and
// matched-policy lists.
func markerCorruptionCases(s markerFixtureSites) []markerAt {
	return []markerAt{
		s.recursive11, // policy recursive = 0
		s.recursive12, // policy recursive = 1
		s.rolledBack1, // change from rollback = 0
		s.disabled2,   // subject disabled = 1
		s.allowed2,    // decision allowed = 0
		s.change1,     // policy-change payload present
		s.decision1,   // decision payload absent on a change record
		s.change2,     // change payload absent on a decision record
		s.decision2,   // decision payload present
		s.policies1,   // policy list present
		s.roles2,      // subject role list present
		s.matched2,    // matched-policy list present
	}
}

// TestArchiveIllegalSingleByteMarkersRejected proves, for every boolean and
// every presence marker in both record kinds, that a byte other than 0/1
// (2 and 255 are both probed) makes the archive unreadable even with a
// correct outer length and checksum: DecodeAuditArchive returns
// ErrInvalidArchive (matched by errors.Is, and never ErrInvalidRange) and
// no records. The failed call rewrites neither the input bytes nor the
// independently retained checkpoint.
func TestArchiveIllegalSingleByteMarkersRejected(t *testing.T) {
	good, _, cp := markerCorruptionFixture(t)
	basePayload := payloadOf(t, good)
	sites := inspectMarkerFixturePayload(t, basePayload)

	expectInvalid := func(site markerAt, bad byte) {
		name := site.name
		t.Helper()
		payload := append([]byte(nil), basePayload...)
		payload[site.at] = bad
		data := framePayload(payload)
		dataSnapshot := append([]byte(nil), data...)
		cpSnapshot := cp

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s <- %d: err = %v, want ErrInvalidArchive", name, bad, err)
		}
		if errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s <- %d: structurally illegal marker counted as a content error: %v", name, bad, err)
		}
		if got != nil {
			t.Fatalf("%s <- %d: returned %d records, want nil", name, bad, len(got))
		}
		if !bytes.Equal(data, dataSnapshot) {
			t.Fatalf("%s <- %d: failed decode rewrote the archive bytes", name, bad)
		}
		if cp != cpSnapshot {
			t.Fatalf("%s <- %d: failed decode rewrote the checkpoint", name, bad)
		}
	}

	for _, site := range markerCorruptionCases(sites) {
		if site.want != 0 && site.want != 1 {
			t.Fatalf("internal fixture error: %s legal byte = %d", site.name, site.want)
		}
		for _, bad := range []byte{2, 255} {
			if bad == site.want {
				continue
			}
			expectInvalid(site, bad)
		}
	}

	// A broader sweep pins the "only 0 and 1 are legal" rule rather than the
	// two named values alone: every other byte value is rejected at one
	// boolean and one presence position of each kind.
	probes := append([]markerAt{}, sites.allowed2, sites.change1, sites.policies1, sites.roles2, sites.matched2)
	for _, site := range probes {
		for bad := byte(3); bad < 255; bad++ {
			if bad == site.want {
				continue
			}
			payload := append([]byte(nil), basePayload...)
			payload[site.at] = bad
			if got, err := DecodeAuditArchive(framePayload(payload), "acme", cp); !errors.Is(err, ErrInvalidArchive) || got != nil {
				t.Fatalf("%s <- %d: records=%v err=%v, want ErrInvalidArchive, nil", site.name, bad, got, err)
			}
			if bad == 250 {
				break // representative mid-range sample is enough per site
			}
		}
	}
}

// TestArchiveLegalBooleanFlipsAreContentErrors keeps format damage separate
// from altered content: flipping a legal boolean byte between 0 and 1
// leaves every length, marker and frame intact and the checksum is
// recomputed, so the material is fully readable as a format. Its audit
// content has nonetheless changed, and read against the original retained
// fingerprint and external checkpoint it must fail the whole read with
// ErrInvalidRange — never be swept into ErrInvalidArchive — and deliver no
// records.
func TestArchiveLegalBooleanFlipsAreContentErrors(t *testing.T) {
	good, _, cp := markerCorruptionFixture(t)
	basePayload := payloadOf(t, good)
	sites := inspectMarkerFixturePayload(t, basePayload)

	flips := []markerAt{
		s.recursive11, // 0 -> 1
		s.recursive12, // 1 -> 0
		s.rolledBack1, // 0 -> 1
		s.disabled2,   // 1 -> 0
		s.allowed2,    // 0 -> 1
	}
	for _, site := range flips {
		payload := append([]byte(nil), basePayload...)
		payload[site.at] ^= 1 // legal 0<->1 flip; length and framing unchanged
		data := framePayload(payload)

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s flip: err = %v, want ErrInvalidRange", site.name, err)
		}
		if errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s flip: a readable-format content change reported as archive damage: %v", site.name, err)
		}
		if got != nil {
			t.Fatalf("%s flip: returned %d records on chain mismatch, want nil", site.name, len(got))
		}
	}

	// The distinction survives on the successful-read side too: the
	// flipped-bool payload re-encoded with the checkpoint its own altered
	// chain would carry is a format the decoder accepts, proving the flip
	// changed content rather than breaking the format. A flipped Allowed
	// changes only that record's fingerprint, so decoding it against a
	// matching checkpoint must succeed through the format layer (the chain
	// check then compares fingerprints, not the retained one used above).
	allowedFlip := append([]byte(nil), basePayload...)
	allowedFlip[sites.allowed2.at] = 1
	altered := framePayload(allowedFlip)
	if _, err := DecodeAuditArchive(altered, "acme", cp); !errors.Is(err, ErrInvalidRange) {
		t.Fatalf("control: flipped Allowed against retained checkpoint err = %v, want ErrInvalidRange", err)
	}
}

// TestArchiveLaterRecordIllegalMarkerDiscardsPrefix is the read-boundary
// case the requirement names: earlier publish and decision records are all
// intact, and only a later record carries an illegal marker. The complete
// read must still fail with ErrInvalidArchive and never hand back the
// readable prefix as a successful result.
func TestArchiveLaterRecordIllegalMarkerDiscardsPrefix(t *testing.T) {
	thirdReason := "third-decision-disabled-9c2e"
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 1, Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: thirdReason, Matched: []string{"p1"}, Version: 1},
			}
		},
	})
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}

	// The third record's matched list follows its unique reason string:
	// reason bytes, then one presence marker. Rewrite only that marker.
	damaged := reframe(t, good, func(payload []byte) []byte {
		idx := bytes.Index(payload, []byte(thirdReason))
		if idx < 0 {
			t.Fatal("third-record reason not found")
		}
		if bytes.Index(payload[idx+1:], []byte(thirdReason)) >= 0 {
			t.Fatal("third-record reason must be unique for an unambiguous locate")
		}
		markerAt := idx + len(thirdReason)
		if payload[markerAt] != archiveTagPresent {
			t.Fatalf("matched list marker = %d, want present", payload[markerAt])
		}
		payload[markerAt] = 255
		return payload
	})

	dataSnapshot := append([]byte(nil), damaged...)
	cpSnapshot := cp
	got, err := DecodeAuditArchive(damaged, "acme", cp)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("later-record illegal marker: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
	if errors.Is(err, ErrInvalidRange) {
		t.Fatalf("later-record illegal marker counted as a content error: %v", err)
	}
	if !bytes.Equal(damaged, dataSnapshot) {
		t.Fatal("failed decode rewrote the archive bytes")
	}
	if cp != cpSnapshot {
		t.Fatal("failed decode rewrote the checkpoint")
	}
}

// TestArchiveEmbeddedCheckpointCannotBypassMarkerRejection proves the
// file-carried checkpoint is never a substitute for the caller's evidence:
// even material whose embedded checkpoint matches its own (corrupted)
// content is rejected at the format layer before either checkpoint could
// matter, and on a merely flipped legal boolean the embedded checkpoint
// still cannot authorize a read pinned by the retained one.
func TestArchiveEmbeddedCheckpointCannotBypassMarkerRejection(t *testing.T) {
	good, _, cp := markerCorruptionFixture(t)
	basePayload := payloadOf(t, good)
	sites := inspectMarkerFixturePayload(t, basePayload)

	// Illegal marker, outer checksum valid: rejected regardless of what the
	// embedded checkpoint says — it still carries the original checkpoint.
	payload := append([]byte(nil), basePayload...)
	payload[sites.allowed2.at] = 2
	if got, err := DecodeAuditArchive(framePayload(payload), "acme", cp); !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("illegal marker with intact embedded checkpoint: records=%v err=%v", got, err)
	}

	// A flipped legal boolean with the embedded end sequence rewritten to a
	// plausible value must still fail against the retained checkpoint.
	flipped := append([]byte(nil), basePayload...)
	flipped[sites.allowed2.at] = 1
	rewritten := framePayload(flipped)
	// Overwrite the embedded end-sequence word (header: u32 orgLen, org, u32).
	pos := 4 + len("acme")
	binary.BigEndian.PutUint32(rewritten[len(archiveMagic)+4+pos:], 2)
	sum := sha256PayloadPortion(rewritten)
	copy(rewritten[len(rewritten)-32:], sum)
	if got, err := DecodeAuditArchive(rewritten, "acme", cp); !errors.Is(err, ErrInvalidRange) || got != nil {
		t.Fatalf("flipped bool with rewritten embedded checkpoint: records=%v err=%v, want ErrInvalidRange", got, err)
	}
}

// sha256PayloadPortion recomputes the trailing checksum word of one framed
// archive after its payload was edited in place, mirroring framePayload.
func sha256PayloadPortion(archive []byte) []byte {
	magicLen := len(archiveMagic)
	n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
	payload := archive[magicLen+4 : magicLen+4+n]
	sum := sha256Sum(payload)
	return sum
}

// TestArchiveValidMarkerFixtureRoundTrip is the uncorrupted control the
// guards must never disturb: the full fixture decodes with both boolean
// values and the nil / non-nil-empty / populated list shapes intact,
// verifies against the retained checkpoint, and still serves offline
// review. It additionally locks the three list shapes directly through
// synthetic records carrying nil, empty and populated policies, roles and
// matched lists.
func TestArchiveValidMarkerFixtureRoundTrip(t *testing.T) {
	archive, recs, cp := markerCorruptionFixture(t)
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("valid fixture decode: %v", err)
	}
	if !reflect.DeepEqual(got, recs) {
		t.Fatalf("valid fixture changed across the archive:\n got %+v\nwant %+v", got, recs)
	}

	// Both boolean values survive at every position they occupy.
	pols := got[0].Change.Policies
	if pols[0].Recursive || !pols[1].Recursive {
		t.Fatalf("Recursive values lost: %v, %v", pols[0].Recursive, pols[1].Recursive)
	}
	if got[0].Change.RolledBack {
		t.Fatal("RolledBack=false decoded as true")
	}
	if !got[1].Decision.Request.Subject.Disabled {
		t.Fatal("Disabled=true decoded as false")
	}
	if got[1].Decision.Decision.Allowed {
		t.Fatal("Allowed=false decoded as true")
	}
	// Presence shapes of the store-built fixture.
	if got[0].Change == nil || got[0].Decision != nil {
		t.Fatal("record 1 payload shapes changed")
	}
	if got[1].Change != nil || got[1].Decision == nil {
		t.Fatal("record 2 payload shapes changed")
	}
	if got[0].Change.Policies == nil || len(got[0].Change.Policies) != 2 {
		t.Fatal("populated policy list lost")
	}
	if !reflect.DeepEqual(got[1].Decision.Request.Subject.Roles, []string{"reader"}) {
		t.Fatalf("roles lost: %q", got[1].Decision.Request.Subject.Roles)
	}
	if len(got[1].Decision.Decision.Matched) != 0 {
		t.Fatalf("disabled denial matched list must be empty, got %q", got[1].Decision.Decision.Matched)
	}

	if err := VerifyAudit("acme", got, cp); err != nil {
		t.Fatalf("decoded fixture must verify: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil || !review.Consistent {
		t.Fatalf("fixture must remain reviewable: review=%+v err=%v", review, err)
	}

	// Explicit nil vs non-nil-empty vs populated list shapes across both
	// payload kinds, with booleans exercising both values.
	req := request("acme", "u1", "r1", "org/a", "read")
	shapes, shapeCP := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil, RolledBack: false}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 2, SourceVersion: 1, RolledBack: true, Policies: []Policy{},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{
				allowPolicy("p1", "u1", "read", "org/a", false),
				allowPolicy("p2", "u1", "read", "org/a", true),
			}}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = nil
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: nil, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{}
			r.Subject.Disabled = false
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: []string{}, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{"reader"}
			r.Subject.Disabled = true
			return AuditDecision, nil, &DecisionRecord{
				Request: r,
				Decision: Decision{Allowed: false, Reason: "subject is disabled",
					Matched: []string{}, Version: 0},
			}
		},
	})
	arch, err := EncodeAuditArchive("acme", shapes, shapeCP)
	if err != nil {
		t.Fatalf("encode shapes: %v", err)
	}
	back, err := DecodeAuditArchive(arch, "acme", shapeCP)
	if err != nil {
		t.Fatalf("decode shapes: %v", err)
	}
	if !reflect.DeepEqual(back, shapes) {
		t.Fatalf("list/boolean shapes changed:\n got %+v\nwant %+v", back, shapes)
	}
	if back[0].Change.Policies != nil {
		t.Fatal("nil policy list decoded non-nil")
	}
	if back[1].Change.Policies == nil || len(back[1].Change.Policies) != 0 {
		t.Fatal("non-nil empty policy list lost shape")
	}
